CREATE COLUMN TABLE "TEST_AP"."ARST" ("AbsEntry" INTEGER CS_INT NOT NULL , "Code" NVARCHAR(50) NOT NULL , "Desc" NVARCHAR(100), "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "CreateDate" LONGDATE CS_LONGDATE, "CreateTime" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , PRIMARY KEY ("AbsEntry", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ARST_SECONDARY" ON "TEST_AP"."ARST" ( "Code" ASC, "LogInstanc" ASC )